367	/**
368	 * Moves the claim to the action's status; refused (400) when the claim's status does not allow it.
369	 * Opening gives the claim the sheet's next number; voiding clears it (the number is not reused).
370	 * Opening records the user who opened it; that user cannot settle it (four eyes).
371	 * Settling fixes the claim's due at its person's grade's rate in force on the claim's date; with no rate it stays live.
372	 */
373	public class ApplyClaimAction {
374	    public void apply(@PathVariable("action") String action, @RequestParam("user") String user, @Val Claim claim, SheetRepository sheets,
375	            PersonRepository people, RateRepository rates,
376	            Out<ClaimAction> applied, Out<ClaimNumber> number, Out<Claim> updated) throws InvalidClaimException {
377	        ClaimAction found = ClaimAction.of(action);
378	        if (found == null) {
379	            throw new InvalidClaimException("No such claim action: " + action);
380	        }
381	        if (!found.allowedFrom(claim.status())) {
382	            throw new InvalidClaimException("A " + claim.status() + " claim cannot be " + found.to() + ".");
383	        }
384	        if (found == ClaimAction.SETTLE && user.equals(claim.openedBy())) {
385	            throw new InvalidClaimException("The user who opened a claim cannot settle it.");
386	        }
387	        Integer next = switch (found) {
388	            case OPEN -> sheets.nextClaimNumber(claim.sheetId());
389	            case VOID -> null;
390	            default -> claim.number();
391	        };
392	        applied.set(found);
393	        number.set(new ClaimNumber(found == ClaimAction.VOID ? claim.number() : next));
394	        BigDecimal due = found == ClaimAction.SETTLE ? settledDue(claim, people, rates) : claim.due();
395	        updated.set(claim.withStatus(found.to(), next, due, found == ClaimAction.OPEN ? user : claim.openedBy()));
396	    }
397	
398	    private static BigDecimal settledDue(Claim claim, PersonRepository people, RateRepository rates) {
399	        Person person = people.find(claim.sheetId(), claim.personId());
400	        BigDecimal rate = person == null ? null
401	                : Rate.inForce(rates.findAll(claim.sheetId()), person.grade(), claim.date());
402	        return Claim.due(claim.amount(), rate);
403	    }
404	}
