489	public enum ClaimAction {
490	    OPEN("open", ClaimStatus.OPEN, "CLAIM_OPENED", ClaimStatus.DRAFT),
491	    SETTLE("settle", ClaimStatus.SETTLED, "CLAIM_SETTLED", ClaimStatus.OPEN),
492	    VOID("void", ClaimStatus.VOID, "CLAIM_VOIDED", ClaimStatus.DRAFT, ClaimStatus.OPEN);
493	
494	    private final String path;
495	    private final ClaimStatus to;
496	    private final String event;
497	    private final ClaimStatus[] from;
