499	    ClaimAction(String path, ClaimStatus to, String event, ClaimStatus... from) {
500	        this.path = path;
501	        this.to = to;
502	        this.event = event;
503	        this.from = from;
504	    }
505	
506	    /** The action named in the path, or null. */
507	    public static ClaimAction of(String path) {
508	        for (ClaimAction action : values()) {
509	            if (action.path.equals(path)) {
510	                return action;
511	            }
512	        }
513	        return null;
514	    }
515	
516	    public boolean allowedFrom(ClaimStatus status) {
517	        for (ClaimStatus s : from) {
518	            if (s == status) {
519	                return true;
520	            }
521	        }
522	        return false;
523	    }
524	
525	    public ClaimStatus to() {
526	        return to;
527	    }
528	
529	    public String event() {
530	        return event;
531	    }
