596	
597	    private static final String COLUMNS = "id, sheet_id, person_id, amount, claim_date, note, status, claim_number, due, opened_by";
598	
599	    private final JdbcTemplate jdbc;
600	
601	    public ClaimRepository(JdbcTemplate jdbc) {
602	        this.jdbc = jdbc;
603	    }
604	
605	    /** The sheet's claims, newest first. */
606	    public List<Claim> findAll(String sheetId) {
607	        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? ORDER BY id DESC",
608	                ClaimRepository::map, sheetId);
609	    }
610	
611	    /** The claim with this id on this sheet, or null. */
612	    public Claim find(String sheetId, long id) {
613	        List<Claim> found = jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND id = ?",
614	                ClaimRepository::map, sheetId, id);
615	        return found.isEmpty() ? null : found.get(0);
616	    }
617	
618	    /** Insert a new claim (null id) or update an existing one; the claim as stored. */
619	    public Claim save(Claim claim) {
620	        if (claim.id() != null) {
621	            jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, claim_number = ?, due = ?, opened_by = ? WHERE id = ? AND sheet_id = ?",
622	                    claim.amount(), Date.valueOf(claim.date()), claim.note(), claim.status().name(), claim.number(),
623	                    claim.due(), claim.openedBy(), claim.id(), claim.sheetId());
624	            return claim;
625	        }
626	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
627	        jdbc.update(con -> {
628	            PreparedStatement ps = con.prepareStatement(
629	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, status) VALUES (?, ?, ?, ?, ?, ?)",
630	                    new String[] { "id" });
631	            ps.setString(1, claim.sheetId());
632	            ps.setLong(2, claim.personId());
633	            ps.setBigDecimal(3, claim.amount());
634	            ps.setDate(4, Date.valueOf(claim.date()));
635	            ps.setString(5, claim.note());
636	            ps.setString(6, claim.status().name());
637	            return ps;
638	        }, keys);
639	        return new Claim(keys.getKey().longValue(), claim.sheetId(), claim.personId(), claim.amount(), claim.date(),
640	                claim.note(), claim.status(), claim.number(), claim.due(), claim.openedBy());
641	    }
642	
643	    private static Claim map(ResultSet rs, int n) throws SQLException {
644	        return new Claim(rs.getLong("id"), rs.getString("sheet_id"), rs.getLong("person_id"),
645	                rs.getBigDecimal("amount").setScale(2), rs.getDate("claim_date").toLocalDate(), rs.getString("note"),
646	                ClaimStatus.valueOf(rs.getString("status")), rs.getObject("claim_number", Integer.class),
647	                rs.getBigDecimal("due"), rs.getString("opened_by"));
648	    }
649	}
