855	/**
856	 * A rate a sheet has for a grade: a percent with two decimals, in force from {@code from} (null: from
857	 * the beginning of time) until the grade's next rate takes over.
858	 */
859	public record Rate(String sheetId, String grade, BigDecimal rate, LocalDate from) {
860	
861	    /** The grade's rate in force on the date: the one with the latest from-date on or before it; null with none. */
862	    public static BigDecimal inForce(List<Rate> rates, String grade, LocalDate date) {
863	        return rates.stream()
864	                .filter((r) -> r.grade().equals(grade) && (r.from() == null || !r.from().isAfter(date)))
865	                .max(Comparator.comparing(Rate::from, Comparator.nullsFirst(Comparator.naturalOrder())))
866	                .map(Rate::rate).orElse(null);
867	    }
